'use server'

import { revalidatePath } from 'next/cache'

// In a real app, this would come from your database
let userNotificationPreference = false

export async function getNotificationPreference(): Promise<boolean> {
  return userNotificationPreference
}

export async function toggleNotificationPreference(): Promise<void> {
  // Toggle the preference
  userNotificationPreference = !userNotificationPreference

  // Revalidate the current page to show the updated preference
  revalidatePath('/')
}

