import { getNotificationPreference, toggleNotificationPreference } from './actions'

export default async function Home() {
  const notificationsEnabled = await getNotificationPreference()

  return (
    <main>
      <h1>Settings</h1>
      <form action={toggleNotificationPreference}>
        <label>
          <input
            type="checkbox"
            name="notifications"
            defaultChecked={notificationsEnabled}
            onChange={(e) => e.target.form?.requestSubmit()}
          />
          Enable Notifications
        </label>
      </form>
      <p>Notifications are currently {notificationsEnabled ? 'ON' : 'OFF'}</p>
    </main>
  )
}

